SELECT 'public.update_candidate_onboarding_details(text,text,text,text,boolean,text,boolean,text)' name,EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.update_candidate_onboarding_details(text,text,text,text,boolean,text,boolean,text)') AND md5(p.prosrc)='2c3d9fddfb01b2c77c176e880798dde3' AND p.prosecdef AND p.provolatile='v' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND (p.proconfig @> ARRAY['search_path='] OR p.proconfig @> ARRAY['search_path=""']) AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND has_function_privilege('authenticated',p.oid,'EXECUTE')=true) ok
