UNION ALL
SELECT 'private.resume_application_recipients(uuid)',EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('private.resume_application_recipients(uuid)') AND md5(prosrc)='e044e66d076088aef544e6b9ad4830ee' AND prosecdef AND pg_get_userbyid(proowner)='postgres' AND NOT has_function_privilege('anon',oid,'EXECUTE') AND has_function_privilege('authenticated',oid,'EXECUTE')=false)
UNION ALL
SELECT 'private.current_resume_recipient(text)',EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('private.current_resume_recipient(text)') AND md5(prosrc)='18d8c3b5e8f57a7a745e9218015ca6a4' AND prosecdef AND pg_get_userbyid(proowner)='postgres' AND NOT has_function_privilege('anon',oid,'EXECUTE') AND has_function_privilege('authenticated',oid,'EXECUTE')=false)
UNION ALL
SELECT 'private.can_read_shared_candidate_resume(text)',EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('private.can_read_shared_candidate_resume(text)') AND md5(prosrc)='3a3f6d9d12b973f9be19ee459316aee5' AND prosecdef AND pg_get_userbyid(proowner)='postgres' AND NOT has_function_privilege('anon',oid,'EXECUTE') AND has_function_privilege('authenticated',oid,'EXECUTE')=true)
UNION ALL
SELECT 'private_grants',EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('private.candidate_resume_shares') AND relrowsecurity) AND NOT has_any_column_privilege('authenticated','private.candidate_resume_shares','SELECT,INSERT,UPDATE,REFERENCES') AND NOT has_any_column_privilege('anon','private.candidate_resume_shares','SELECT,INSERT,UPDATE,REFERENCES')
UNION ALL
SELECT 'onboarding_rls_acl',EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.candidate_onboarding_details') AND relrowsecurity) AND NOT has_any_column_privilege('authenticated','public.candidate_onboarding_details','SELECT,INSERT,UPDATE,REFERENCES') AND NOT has_any_column_privilege('anon','public.candidate_onboarding_details','SELECT,INSERT,UPDATE,REFERENCES')
UNION ALL
SELECT 'new_constraints',(SELECT count(*)=4 AND bool_and(convalidated) FROM pg_constraint WHERE (conrelid=to_regclass('private.candidate_resume_shares') AND conname IN ('candidate_sharing_mode_check','candidate_sharing_item_check','candidate_sharing_item_unique')) OR (conrelid=to_regclass('public.candidate_onboarding_details') AND conname='candidate_onboarding_full_account_check'))
UNION ALL
SELECT 'onboarding_revision_trigger',EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass('public.candidate_onboarding_details') AND tgname='candidate_onboarding_sharing_revision' AND tgenabled='O' AND tgfoid=to_regprocedure('private.rotate_onboarding_share_revision()'))
UNION ALL
SELECT 'storage_recipient_policy',EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Recipients read Admin shared resumes' AND cmd='SELECT' AND roles=ARRAY['authenticated']::name[] AND qual='((bucket_id = ''candidate-private''::text) AND private.can_read_shared_candidate_resume(name))')
) SELECT string_agg(name,',' ORDER BY name) INTO failed FROM checks WHERE NOT coalesce(ok,false);
IF failed IS NOT NULL THEN RAISE EXCEPTION 'Document sharing postcheck mismatch: %',failed; END IF; END $post$;
NOTIFY pgrst,'reload schema';
COMMIT;
SELECT 'ADMIN_DOCUMENT_REPAIR=COMMITTED';
